 void moveNPCs(List<Object>npcs,float dt){for(Object o:npcs){Map<String,Object>n=map(o);n.put("walking",false);List<Object>patrol=list(n.get("patrol"));if(patrol.isEmpty()||Math.hypot(number(n.get("px"))-number(player().get("x")),number(n.get("py"))-number(player().get("y")))<65)continue;Object to=patrol.get(integer(n.get("patrolIndex")));double dx=number(get(to,"x"))*32+16-number(n.get("px")),dy=number(get(to,"y"))*32+20-number(n.get("py")),length=Math.hypot(dx,dy);if(length<2){n.put("patrolIndex",(integer(n.get("patrolIndex"))+1)%patrol.size());continue;}Map<String,Object>actor=obj(kv("x",n.get("px")),kv("y",n.get("py")));double ox=number(actor.get("x")),oy=number(actor.get("y"));List<Object>collision=new ArrayList<>(npcs);collision.add(obj(kv("id","player"),kv("px",player().get("x")),kv("py",player().get("y"))));world.move(actor,dx/length*18*dt,dy/length*18*dt,flags(),collision,str(n.get("id")),7);n.put("px",actor.get("x"));n.put("py",actor.get("y"));n.put("walking",Math.hypot(number(actor.get("x"))-ox,number(actor.get("y"))-oy)>.01);n.put("direction",Math.abs(dx)>Math.abs(dy)?dx>0?"right":"left":dy>0?"down":"up");}}
