 void finishDialogue(){Map<String,Object>doneScript=script,n=speaker;call(doneScript.get("onFinish"),args());dialogueOpen=false;overlay.setVisibility(View.GONE);if(doneScript.get("travel")!=null){Map<String,Object>r=world.byId(str(doneScript.get("travel")));player().put("x",(number(r.get("x"))+12)*32+16);player().put("y",(number(r.get("y"))+19)*32+16);player().put("direction","up");world.cameraReady=false;}changed();if(doneScript.get("encounter")!=null){showEncounter(n);return;}if(truth(flags().get("solved"))&&!truth(flags().get("celebrated"))){flags().put("celebrated",true);showEnding();}}
