 void showEncounter(Map<String,Object>n){if(!truth(rules.run("encounterAllowed",session,n.get("id"))))return;Object identity=rules.run("storyIdentity",n,session.get("character"));Object detail=list(data.get("ENCOUNTERS")).stream().filter(v->equal(get(v,"id"),n.get("id"))).findFirst().orElse(obj(kv("context","S-12 · Prova opcional da Encruzilhada."),kv("mark","OPCIONAL")));LinearLayout panel=book(str(get(session.get("character"),"name"))+" × "+str(get(identity,"name")),"FRATURAS · "+(truth(get(detail,"mark"))?str(get(detail,"mark")):"CONFRONTO "+str(get(detail,"number"))));LinearLayout portraits=row();portraits.setGravity(Gravity.CENTER);portraits.addView(new SpriteView(session.get("character"),"down"),new LinearLayout.LayoutParams(d(84),d(96)));TextView vs=text("  VS  ",24,0xff9b4b36,true);portraits.addView(vs);portraits.addView(new SpriteView(rules.run("npcCharacter",identity),"down"),new LinearLayout.LayoutParams(d(84),d(96)));add(panel,portraits,-2,10);add(panel,text(str(get(detail,"context")),14,INK,false),-2,14);add(panel,button("Ir para a luta",true,()->launchFight(map(identity))),-2,8);add(panel,button("Preparar-me primeiro",false,this::closeOverlay),-2,0);}
 void launchFight(Map<String,Object>n){pendingEncounter=str(n.get("id"));battlePending=true;clearInput();save();Intent intent=WorldBattleBridge.intent(this,session,n,rules);closeOverlay();startActivityForResult(intent,FIGHT);}
 @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(request!=FIGHT)return;String encounter=pendingEncounter;pendingEncounter=null;battlePending=false;if(result==RESULT_OK&&intent!=null&&intent.getBooleanExtra("world_victory",false)&&encounter!=null&&truth(rules.run("encounterAllowed",session,encounter))){rules.run("completeEncounter",session,encounter);changed();if(encounter.equals("thanos")){flags().put("celebrated",true);showEnding();}else{toast(encounterConsequence(encounter));if(encounter.equals("doom")){Object n=actors.stream().filter(v->encounter.equals(get(v,"id"))).findFirst().orElse(null);if(n!=null)handler.postDelayed(()->{if(!paused()&&session!=null)openConversation(map(n));},250);}}}else{changed();toast("A investigação continua. Prepare-se e tente o encontro novamente.");}}
 String encounterConsequence(String id){switch(id){
  case "station-guard":return "A patrulha foi desativada. As vozes registradas por Eddie levam à Torre Stark.";
  case "defender":return "FRIDAY confirma: a energia acompanha você. A Oscorp está acessível.";
  case "osc-guards":return "O agente não conseguiu destruir as provas. Recolha o fragmento menor para Strange.";
  case "strange":return truth(flags().get("R1"))?"Quatro Pilares estão sendo reunidos. O portal de Wakanda abriu.":"Strange entrega o Anel. O portal de Wakanda abriu.";
  case "panther":return "Okoye acena. Birnin Zana recebe você.";
  case "spider":return "Aranha confirma a falha na ordem. A contenção do Fragmento protegeu o mercado.";
  case "widow":return "Natasha encontrou a assinatura falsa. O laboratório está acessível.";
  case "mine-guard":return "A extração foi interrompida. A Câmara de Ressonância abriu.";
  case "hulk":return truth(flags().get("R2"))?"O Monarca drena o Pilar II. O Portal Harmônico está pronto.":"Bruce respira. O Portal Harmônico está pronto.";
  case "marvel":return "Quarentena levantada. Procure Sif e Frigga.";
  case "thor":return "Odin despertou. Volte ao Salão para abrir o Bifrost.";
  case "wolverine":return "Logan reconhece o teste de Destino. Examine o selo no poste.";
  case "leader":return "O Capitão autorizou o assalto a Latveria.";
  case "armory-guard":return "A defesa do circuito caiu. O Laboratório dos Pilares está aberto.";
  case "scarlet":return "O colar quebrou. Wanda pode voltar a escolher.";
  case "doom":return "Destino cai de joelhos. Thanos atravessa os espelhos.";
  case "thanos":return "O Fragmento reverteu o Núcleo. Seu universo sobreviveu.";
  default:return "Encontro concluído. O dossiê guarda suas escolhas.";}}
 void showJournal(){if(paused())return;LinearLayout panel=book("Dossiê de Fraturas","PISTAS · CAMINHOS · ENCONTROS");add(panel,text("Próximo passo: "+get(rules.run("objective",session),"text")+" · Pistas "+str(rules.run("clueCount",session))+"/12 · Aliados Plenos "+list(rules.run("fullAllies",session)).size()+"/16"+(session.get("eco")!=null?" · ECO":""),14,INK,false),-2,15);List<Object>notes=list(session.get("notes"));if(notes.isEmpty())add(panel,text("O dossiê está em branco. Ouça Rosa e Marcus.",12,0xff69755e,false),-2,13);for(int i=notes.size()-1;i>=0;i--){Object n=notes.get(i);TextView title=text(str(get(n,"title")),16,INK,false);title.setTypeface(Typeface.SERIF,Typeface.BOLD);add(panel,title,-2,5);add(panel,text(str(get(n,"text")),12,0xff69755e,false),-2,13);View rule=new View(this);rule.setBackgroundColor(0xffbda97a);add(panel,rule,1,13);}add(panel,text("Quem se lembra de você",18,INK,false),-2,10);List<Object>allies=new ArrayList<>(list(data.get("ALLIES")));for(String id:map(session.get("relationships")).keySet())if(!allies.contains(id))allies.add(id);for(Object id:allies){Object hero=rules.run("heroById",id),n=hero!=null?hero:world.npcs.stream().filter(v->equal(get(v,"id"),id)).findFirst().orElse(obj(kv("name",id)));int value=integer(get(session.get("relationships"),id));add(panel,text(get(n,"name")+" · "+value+"/2 · "+(value==2?"Aliado Pleno":value==1?"respeito":"distância"),12,INK,false),-2,7);}}
