 void showExit(){if(paused())return;LinearLayout panel=book("Voltar ao Story Mode?","FIM DA SESSÃO");add(panel,text("Ao sair da ilha, esta exploração termina. Na próxima visita, você escolhe um protagonista e começa uma nova jornada.",14,INK,false),-2,18);add(panel,button("Continuar explorando",true,this::closeOverlay),-2,9);add(panel,button("Voltar ao Story Mode",false,this::exit),-2,0);}
