 @Override public void onBackPressed(){if(dialogueOpen){dialogueOpen=false;overlay.setVisibility(View.GONE);changed();}else if(modal)closeOverlay();else if(creating)exit();else showExit();}
 @Override public boolean onKeyDown(int code,KeyEvent e){String dir=keyDirection(code);if(dir!=null&&!paused()){keys.add(dir);return true;}if(code==KeyEvent.KEYCODE_E||code==KeyEvent.KEYCODE_ENTER){interact();return true;}if(code==KeyEvent.KEYCODE_J){showJournal();return true;}if(code==KeyEvent.KEYCODE_M){showMap();return true;}return super.onKeyDown(code,e);}
 @Override public boolean onKeyUp(int code,KeyEvent e){String dir=keyDirection(code);if(dir!=null){keys.remove(dir);return true;}return super.onKeyUp(code,e);}String keyDirection(int c){if(c==KeyEvent.KEYCODE_W||c==KeyEvent.KEYCODE_DPAD_UP)return "up";if(c==KeyEvent.KEYCODE_S||c==KeyEvent.KEYCODE_DPAD_DOWN)return "down";if(c==KeyEvent.KEYCODE_A||c==KeyEvent.KEYCODE_DPAD_LEFT)return "left";if(c==KeyEvent.KEYCODE_D||c==KeyEvent.KEYCODE_DPAD_RIGHT)return "right";return null;}
 final class WorldView extends View {WorldView(){super(VisitWorldActivity.this);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}float zoom(){return getResources().getDisplayMetrics().density*2;}float logicalWidth(){return getWidth()/zoom();}float logicalHeight(){return getHeight()/zoom();}protected void onDraw(Canvas c){super.onDraw(c);c.save();c.scale(zoom(),zoom());if(creating){List<Object>initial=new ArrayList<>();for(Object n:actors)if(get(n,"requires")==null)initial.add(n);art.render(c,null,initial,arr(),logicalWidth(),logicalHeight(),time,null,null);}else art.render(c,session,visible(actors),visible(objects),logicalWidth(),logicalHeight(),time,paused()?null:nearest,str(get(rules.run("objective",session),"target")));c.restore();}public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()!=MotionEvent.ACTION_DOWN||paused())return true;double x=e.getX()/zoom()+world.cameraX,y=e.getY()/zoom()+world.cameraY;List<Object>candidates=visible(actors);candidates.addAll(visible(objects));candidates.sort((a,b)->Double.compare(number(get(b,"py")),number(get(a,"py"))));for(Object n:candidates)if(Math.hypot(number(get(n,"px"))-number(player().get("x")),number(get(n,"py"))-number(player().get("y")))<45&&Math.abs(number(get(n,"px"))-x)<23&&y>=number(get(n,"py"))-45&&y<=number(get(n,"py"))+10){openConversation(map(n));break;}return true;}}
 final class SpriteView extends View {Object character;String direction;SpriteView(Object c,String dir){super(VisitWorldActivity.this);character=c;direction=dir;}protected void onDraw(Canvas c){super.onDraw(c);float scale=Math.min(getWidth()/40f,getHeight()/46f);art.sprite(c,character,getWidth()/2f,getHeight()*.92f,direction,time,false,scale);}}
 final class MapView extends View {boolean large;MapView(boolean large){super(VisitWorldActivity.this);this.large=large;}protected void onDraw(Canvas c){super.onDraw(c);if(session!=null)art.mini(c,session,getWidth(),getHeight(),large);}}
